  WHERE run_id = ANY($admitted);
INSERT INTO runs (run_id, job_id, tenant_id, scheduled_for, due_at, state, attempt)
  VALUES ('r_8c2_20261112T0700Z', 'j_8c2', 't_acme', '2026-11-12T07:00:00Z', '2026-11-12T07:00:12Z', 'SCHEDULED', 0)
