COMMIT;

UPDATE runs
SET state = 'SCHEDULED', worker_id = NULL, lease_until = NULL,
    due_at = now() + interval '30 seconds' * 2 ^ (attempt - 1) * (1 + random() * 0.2),
    last_error = 'lease expired on w-09'
WHERE run_id = 'r_41a_20261111T0900Z' AND attempt = 1;
COMMIT;

BEGIN;
UPDATE runs SET state = 'DEAD', finished_at = now()
WHERE run_id = 'r_41a_20261111T0900Z' AND attempt = 5 AND state = 'FAILED';

SELECT j.*, r.run_id, r.state, r.due_at, r.attempt, r.lease_until
FROM jobs j LEFT JOIN runs r ON r.job_id = j.job_id AND r.state IN ('SCHEDULED', 'ENQUEUED', 'RUNNING')
WHERE j.job_id = 'j_8c2' AND j.tenant_id = 't_acme';
